//! Experimental AI Remove and AI Replace: the AI Retouch tool's modes, one per
//! extension's retouch generator, where a painted area is
//! regenerated by that generator (a hosted model with the user's own key),
//! with what the user wrote for it when it takes text, and kept as a Generate
//! spot whose patch renders without the extension. Everything here is the
//! app's side of one request: what it captures, when its result may still be
//! applied, and what the tool says.
//!
//! The generators are extensions' ([`retouch_generator`]). A request has its
//! region rendered and its answer inverted on a worker thread of its own, so
//! neither does pixel work on the UI thread, and its outcome becomes one
//! History step, named after its generator ("AI Replace"), that appends the
//! spot, so edits made meanwhile survive. It applies only while what it was made from still holds
//! ([`Guard`]): the same photo, load, file, catalog photo, decoded image, AI
//! Denoise source and noise reduction, and the same spots, red eye and Spot
//! Removal and Red Eye panel state. Otherwise it is dropped with
//! [`STALE`], never asked again by itself: each request is one paid call.
//!
//! Every ending clears busy: success, failure, a worker job that panicked or
//! a worker gone (their fallback events), Cancel, the extension disabled,
//! crashed or reloaded (its lifecycle moved), the deadline, another photo or
//! catalog, and quitting. Patches not taken are let go of unless the edit,
//! its History or Before names them, as Select Subject's rasters are.
//!
//! [`retouch_generator`]: crate::app::extensions::retouch_generator
use crate::app::Editor;
use crate::app::develop::tools::subject_mask::Worker;
use crate::app::extensions::retouch_generator::{self, Offer};
use crate::app::task::{Stopping, Task};
use crate::camera_data::CameraImage;
use crate::model::recipe::Recipe;
use crate::model::retouch::{RetouchMode, RetouchOp, RetouchPatch};
use rawmakase_extensions::protocol::RemoteError;
use rawmakase_extensions::protocol::method::{RetouchGenerate, RetouchGenerated};
use rawmakase_extensions::shm::Returned;
use serde_json::Value;
use std::sync::Arc;
use std::sync::atomic::AtomicBool;

/// What painting says while `offer`'s extension waits to be set up.
fn setup_first(offer: &Offer) -> String {
    format!(
        "Set up {} first: Preferences > Extensions > {}",
        offer.extension_name, offer.extension_name
    )
}

/// What a result made from pixels that have since changed says.
pub(in crate::app) const STALE: &str = "The photo changed while removing; paint again";

/// Why AI Remove made no spot; the drawer says so.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) enum Failure {
    Cancelled,
    /// The extension has to be set up first (an API key); its message.
    NeedsSetup(String),
    /// The service can't be reached or won't work now; why.
    Unavailable(String),
    /// The service declined the region's content; why.
    Refused(String),
    /// The generator needs something from the user first (a prompt in its
    /// panel); what, in its words.
    NeedsInput(String),
    Failed(String),
}
impl Failure {
    /// What the tool says, about the generator called `name` (`AI Replace`).
    pub(in crate::app) fn message(&self, name: &str) -> String {
        match self {
            Self::Cancelled => format!("{name} cancelled"),
            Self::NeedsSetup(why) => format!("{name} needs setting up: {why}"),
            Self::Unavailable(why) => format!("{name} is unavailable: {why}"),
            Self::Refused(why) => format!("The service declined this area: {why}"),
            Self::NeedsInput(what) => what.clone(),
            Self::Failed(why) => format!("{name} failed: {why}"),
        }
    }
}

/// A patch a request produced, registered unsaved in the asset store.
#[derive(Debug)]
pub(crate) struct Generated {
    pub(crate) patch: RetouchPatch,
}

/// A request's outcome, tagged with what it was started for.
pub(crate) struct Done {
    pub(crate) load: u64,
    pub(crate) generation: u64,
    pub(crate) result: Result<Generated, Failure>,
}

/// What must still hold when a result arrives for it to be applied, read from
/// the editor when the request starts and again at completion.
#[derive(Clone, Debug, PartialEq)]
pub(in crate::app) struct Guard {
    /// The spots, red eye, camera exposure and the Spot Removal and Red Eye
    /// panels' state ([`subject_mask::content`]).
    ///
    /// [`subject_mask::content`]: crate::app::develop::tools::subject_mask::content
    content: u64,
    /// The settings noise reduction renders with (AI Denoise's switch and
    /// Amount, Color and luminance noise reduction).
    denoise: String,
    /// The AI Denoise source the region was made from, by identity.
    ai: Option<crate::develop::AiSource>,
    /// The decoded image, by identity.
    image: usize,
    load: u64,
    file: Option<crate::storage::Identity>,
    /// The catalog's location and the photo.
    photo: Option<(String, crate::ids::PhotoId)>,
}

/// The noise reduction settings, as a value to compare.
fn denoise(r: &Recipe) -> String {
    serde_json::to_string(&(
        &r.ai_denoise,
        r.noise_luma.to_bits(),
        r.noise_chroma.to_bits(),
        r.effects.chroma_detail.to_bits(),
        r.effects.chroma_smoothness.to_bits(),
        r.effects.luma_detail.to_bits(),
        r.effects.luma_contrast.to_bits(),
    ))
    .unwrap_or_default()
}

/// What [`AiRemove::setup_needed`] holds.
struct SetupNeeded {
    extension: String,
    settings: u64,
    lifecycle: Option<u64>,
}

struct Pending {
    offer: Offer,
    /// The extension's settings' fingerprint when it was sent
    /// ([`Host::settings_fingerprint`]): a `needs_setup` answer blocks only
    /// settings that still hold.
    ///
    /// [`Host::settings_fingerprint`]: crate::app::extensions::Host::settings_fingerprint
    settings: Option<u64>,
    /// The spot to add: the painted shape, with the tool's feather and opacity.
    op: RetouchOp,
    guard: Guard,
    load: u64,
    generation: u64,
    cancel: Arc<AtomicBool>,
    /// The extension's lifecycle when it started: once it moves (disabled,
    /// uninstalled, reloaded, crashed, hung) the request is void.
    lifecycle: u64,
    ai_denoise: bool,
    /// From when it is sent until its outcome: the host's ticket, what it
    /// asked, and what the answer is inverted through.
    sent: Option<Sent>,
}

struct Sent {
    ticket: u64,
    asked: RetouchGenerate,
    /// What was sent, kept to stand outside the painted area of the answer.
    input: Arc<crate::develop::retouch::rendition::Input>,
    rendition: crate::develop::retouch::rendition::Rendition,
    region: crate::develop::retouch::rendition::Region,
}

/// A request waiting for the user's consent to send pixels to the service.
#[derive(Clone, Debug, PartialEq)]
pub(in crate::app) struct Consent {
    pub(in crate::app) offer: Offer,
    pub(in crate::app) op: RetouchOp,
}

pub(in crate::app) struct AiRemove {
    task: Task,
    pending: Option<Pending>,
    worker: Worker,
    /// What the last attempt ended in, for the drawer, until the next.
    pub(in crate::app) failure: Option<Failure>,
    /// The generator a failed request went to and the area it was for: the
    /// photo shows the failure there, as it showed it working, and Set up…
    /// opens that generator's extension.
    pub(in crate::app) failed: Option<(Offer, RetouchOp)>,
    /// An extension that said it needs setting up, with the fingerprint of
    /// the settings the request was sent with and its lifecycle then:
    /// sending to it waits until either moves or the failure is dismissed,
    /// rather than send what would fail the same way.
    setup_needed: Option<SetupNeeded>,
    /// A request waiting for the user to agree to its uploads.
    pub(in crate::app) consent: Option<Consent>,
    /// The strokes painted and not sent yet, in image space: one area, sent
    /// only when the user asks ([`Editor::send_ai_draft`]).
    pub(in crate::app) draft: Vec<Vec<[f32; 2]>>,
    /// The area sent with the request running or asked about, painted again
    /// if no spot is made of it.
    sent_draft: Vec<Vec<[f32; 2]>>,
    /// Strokes Undo took back from the draft, newest last, for Redo.
    undone_strokes: Vec<Vec<[f32; 2]>>,
    /// The tint showing the draft's coverage with its feather, by what it
    /// was drawn from ([`crate::app::develop::tools::retouch_tool`]).
    pub(in crate::app) draft_tint: Option<(u64, eframe::egui::TextureHandle)>,
    /// Patches of results not taken while another request ran, to let go of
    /// once none runs.
    deferred: Vec<String>,
    /// Requests given up on, by extension and ticket, for the host to cancel
    /// at its next poll.
    withdrawn: Vec<(String, u64)>,
    /// Generators' rail icons by file, read once: the image's address, or
    /// none for a file that can't be read.
    icons: std::collections::HashMap<std::path::PathBuf, Option<String>>,
}
impl Default for AiRemove {
    fn default() -> Self {
        Self {
            task: Task::default(),
            pending: None,
            worker: Worker::named("ai-remove"),
            failure: None,
            failed: None,
            setup_needed: None,
            consent: None,
            draft: Vec::new(),
            sent_draft: Vec::new(),
            undone_strokes: Vec::new(),
            draft_tint: None,
            deferred: Vec::new(),
            withdrawn: Vec::new(),
            icons: Default::default(),
        }
    }
}

impl AiRemove {
    /// The shape being removed, while a request runs.
    pub(in crate::app) fn running(&self) -> Option<&RetouchOp> {
        self.pending.as_ref().map(|p| &p.op)
    }
    /// What the running request is called while it runs, after its
    /// generator: `AI Replace…`.
    pub(in crate::app) fn working(&self) -> Option<String> {
        self.pending.as_ref().map(|p| format!("{}…", p.offer.name))
    }
    /// Stops the running request, whatever it is for. One in flight is
    /// withdrawn: its answer can't apply any more, and the host cancels it at
    /// the program.
    pub(in crate::app) fn cancel(&mut self) {
        self.task.invalidate();
        if let Some(Pending {
            offer,
            sent: Some(sent),
            ..
        }) = self.pending.take()
        {
            self.withdrawn.push((offer.extension, sent.ticket));
        }
    }
    pub(in crate::app) fn take_withdrawn(&mut self) -> Vec<(String, u64)> {
        std::mem::take(&mut self.withdrawn)
    }
    /// The photo changed: nothing asked for the previous one applies.
    pub(in crate::app) fn clear_document(&mut self) {
        self.cancel();
        self.failure = None;
        self.failed = None;
        self.draft.clear();
        self.sent_draft.clear();
        self.undone_strokes.clear();
        self.consent = None;
    }
    /// The thread to wait for when quitting, handed to the shared deadline.
    pub(in crate::app) fn stop(&mut self) -> Vec<Stopping> {
        self.cancel();
        self.consent = None;
        vec![self.worker.stop()]
    }
}

impl Editor {
    /// Forgets the last failure, in the drawer and on the photo, and that its
    /// extension needs setting up: set up elsewhere (a permission on the
    /// service), the user says so by dismissing it.
    pub(in crate::app) fn dismiss_ai_failure(&mut self) {
        self.ai_remove.failure = None;
        self.ai_remove.failed = None;
        self.ai_remove.setup_needed = None;
    }
    /// Every retouch generator enabled extensions offer, each a mode of the
    /// Remove tool, with why it can't run now.
    pub(in crate::app) fn ai_remove_offers(&self) -> Vec<(Offer, Option<String>)> {
        self.extensions.retouch_offers()
    }
    /// The retouch generator new AI spots go to: the one chosen
    /// ([`Editor::choose_ai_generator`]), or the first offered when none was
    /// or it is gone, with why it can't run now.
    pub(in crate::app) fn ai_remove_offer(&self) -> Option<(Offer, Option<String>)> {
        let mut offers = self.ai_remove_offers();
        let chosen =
            self.view.retouch.generator.as_ref().and_then(|provenance| {
                offers.iter().position(|(o, _)| &o.provenance == provenance)
            });
        match chosen {
            Some(i) => Some(offers.swap_remove(i)),
            None => offers.into_iter().next(),
        }
    }
    /// New spots go to `offer`'s generator.
    pub(in crate::app) fn choose_ai_generator(&mut self, offer: &Offer) {
        self.view.retouch.generator = Some(offer.provenance.clone());
    }
    /// The rail's generator tools: one for each extension that offers
    /// generators, named and drawn by its first one, in the extensions' order.
    /// Its drawer has a tab for each of them ([`Editor::generator_tabs`]).
    pub(in crate::app) fn rail_generators(&self) -> Vec<Offer> {
        let mut rail: Vec<Offer> = Vec::new();
        for (offer, _) in self.ai_remove_offers() {
            if !rail.iter().any(|o| o.extension == offer.extension) {
                rail.push(offer);
            }
        }
        rail
    }
    /// The tabs of the open AI Retouch drawer: every generator of the
    /// extension it is open on, in its manifest's order. None while it is
    /// closed.
    pub(in crate::app) fn generator_tabs(&self) -> Vec<Offer> {
        use crate::app::develop::state::Tool;
        if !self.view.is(Tool::AiRetouch) {
            return Vec::new();
        }
        let Some((open, _)) = self.ai_remove_offer() else {
            return Vec::new();
        };
        self.ai_remove_offers()
            .into_iter()
            .map(|(o, _)| o)
            .filter(|o| o.extension == open.extension)
            .collect()
    }
    /// What the chosen tab's generator says of itself, below the tabs: only
    /// while there are tabs, and only when it says something.
    pub(in crate::app) fn generator_tab_description(&self) -> Option<String> {
        if self.generator_tabs().len() < 2 {
            return None;
        }
        self.ai_remove_offer()
            .and_then(|(o, _)| o.description)
            .filter(|d| !d.trim().is_empty())
    }
    /// The rail tool the AI Retouch drawer is open on: its extension's
    /// first generator, whichever tab is chosen.
    pub(in crate::app) fn open_rail_generator(&self) -> Option<Offer> {
        use crate::app::develop::state::Tool;
        if !self.view.is(Tool::AiRetouch) {
            return None;
        }
        let (open, _) = self.ai_remove_offer()?;
        self.rail_generators()
            .into_iter()
            .find(|o| o.extension == open.extension)
    }
    /// Whether `offer`'s icon can't be shown `size` points square: missing,
    /// unreadable or not an SVG the app can draw. The rail then shows
    /// [`Icon::Failed`](crate::app::ui::icons::Icon::Failed) and says so; the
    /// app has no icon of its own for a generator.
    pub(in crate::app) fn generator_icon_broken(&mut self, offer: &Offer, size: f32) -> bool {
        self.generator_icon(offer)
            .is_none_or(|uri| crate::app::ui::icons::broken(&self.context, &uri, size))
    }
    /// An extension's rail button, named by its first generator's
    /// `provenance`: opens the tool on the extension's chosen tab (its first
    /// generator until one is chosen), or closes the tool when it is open on
    /// that extension.
    pub(in crate::app) fn toggle_generator(&mut self, provenance: &str) {
        use crate::app::develop::state::Tool;
        let Some(clicked) = self
            .ai_remove_offers()
            .into_iter()
            .map(|(o, _)| o)
            .find(|o| o.provenance == provenance)
        else {
            return;
        };
        let chosen = self.ai_remove_offer().map(|(o, _)| o);
        let on_its_extension = chosen
            .as_ref()
            .is_some_and(|o| o.extension == clicked.extension);
        if self.view.is(Tool::AiRetouch) && on_its_extension {
            self.view.toggle(Tool::AiRetouch);
            return;
        }
        // The tab chosen last on this extension stays; from another one, its
        // first generator.
        if !on_its_extension {
            self.choose_ai_generator(&clicked);
        }
        if !self.view.is(Tool::AiRetouch) {
            self.view.toggle(Tool::AiRetouch);
        }
    }
    /// The address of `offer`'s rail icon, loaded for egui to draw; none when
    /// its file is missing, too large or can't be read.
    /// The file is read once; `currentColor` is drawn white, as the app's own
    /// icons are, for the rail to tint.
    pub(in crate::app) fn generator_icon(&mut self, offer: &Offer) -> Option<String> {
        let path = &offer.icon;
        if let Some(uri) = self.ai_remove.icons.get(path) {
            return uri.clone();
        }
        let svg = std::fs::metadata(path)
            .ok()
            .filter(|m| m.len() <= rawmakase_extensions::MAX_ICON)
            .and_then(|_| std::fs::read_to_string(path).ok());
        let uri = svg.map(|svg| {
            let n = self.ai_remove.icons.len();
            let uri = format!("bytes://rawmakase-generator-icon-{n}.svg");
            self.context.include_bytes(
                uri.clone(),
                svg.replace("currentColor", "#ffffff").into_bytes(),
            );
            uri
        });
        self.ai_remove.icons.insert(path.clone(), uri.clone());
        uri
    }
    /// Adds a stroke (a click is a stroke of one dab) to the area waiting to
    /// be sent, in image space. Nothing is sent: [`Editor::send_ai_draft`]
    /// does that. Past [`MAX_POINTS`] dabs in all, a stroke is left out.
    ///
    /// [`MAX_POINTS`]: crate::model::retouch::MAX_POINTS
    pub(in crate::app) fn add_ai_stroke(&mut self, points: Vec<[f32; 2]>) {
        let total: usize = self.ai_remove.draft.iter().map(Vec::len).sum();
        if points.is_empty() {
            return;
        }
        if total + points.len() > crate::model::retouch::MAX_POINTS {
            self.messages
                .warn("This area has as many strokes as one request takes; send or clear it");
            return;
        }
        self.ai_remove.draft.push(points);
        // Painting anew ends what Redo can bring back.
        self.ai_remove.undone_strokes.clear();
    }
    /// Undo in AI Retouch while an area is painted and not sent: takes back
    /// its newest stroke, for Redo. False when there is none, for History.
    pub(in crate::app) fn undo_ai_stroke(&mut self) -> bool {
        if !self.ai_drafting() {
            return false;
        }
        let Some(stroke) = self.ai_remove.draft.pop() else {
            return false;
        };
        self.ai_remove.undone_strokes.push(stroke);
        true
    }
    /// Redo in AI Retouch: paints again the stroke Undo took back last.
    /// False when there is none, for History.
    pub(in crate::app) fn redo_ai_stroke(&mut self) -> bool {
        if !self.ai_drafting() {
            return false;
        }
        let Some(stroke) = self.ai_remove.undone_strokes.pop() else {
            return false;
        };
        // Within what one request takes, as painting is.
        let total: usize = self.ai_remove.draft.iter().map(Vec::len).sum();
        if total + stroke.len() > crate::model::retouch::MAX_POINTS {
            self.ai_remove.undone_strokes.clear();
            return false;
        }
        self.ai_remove.draft.push(stroke);
        true
    }
    /// Whether Undo would take back a stroke of the area painted.
    pub(in crate::app) fn can_undo_ai_stroke(&self) -> bool {
        self.ai_drafting() && !self.ai_remove.draft.is_empty()
    }
    /// Whether Redo would paint a stroke Undo took back.
    pub(in crate::app) fn can_redo_ai_stroke(&self) -> bool {
        self.ai_drafting() && !self.ai_remove.undone_strokes.is_empty()
    }
    /// Undo went past the area into History: what it took back of the area
    /// can't be redone in History's place.
    pub(in crate::app) fn forget_undone_ai_strokes(&mut self) {
        self.ai_remove.undone_strokes.clear();
    }
    /// Whether AI Retouch is open in Develop, where Undo and Redo reach the
    /// area painted first.
    fn ai_drafting(&self) -> bool {
        self.module == crate::app::Module::Develop && self.ai_retouching()
    }
    /// Forgets the area waiting to be sent.
    pub(in crate::app) fn clear_ai_draft(&mut self) {
        self.ai_remove.draft.clear();
        self.ai_remove.undone_strokes.clear();
    }
    /// Why the area painted can't be sent now, for the drawer's button and
    /// what sending says; none when it can.
    pub(in crate::app) fn ai_send_blocked(&self) -> Option<String> {
        let Some((offer, why)) = self.ai_remove_offer() else {
            return Some("Install AI Retouch in Preferences > Extensions to use it".into());
        };
        if let Some(why) = why.or_else(|| self.ai_remove_unavailable()) {
            return Some(why);
        }
        if self.ai_remove.pending.is_some() {
            return Some(format!("{} is still working on the last area", offer.name));
        }
        if self.ai_remove.consent.is_some() {
            return Some("Send or cancel the area asked about first".into());
        }
        if self.ai_remove.draft.is_empty() {
            return Some("Paint over an area first".into());
        }
        if self.ai_setup_needed(&offer) {
            return Some(setup_first(&offer));
        }
        None
    }
    /// Sends the area painted to the chosen generator as one spot, with the
    /// brush's size, feather and opacity now; the area is forgotten once the
    /// request starts or asks for consent. A send that can't go says why and
    /// keeps the area.
    pub(in crate::app) fn send_ai_draft(&mut self) {
        if let Some(why) = self.ai_send_blocked() {
            self.messages.warn(why);
            return;
        }
        let t = &self.view.retouch;
        let op = RetouchOp {
            mode: RetouchMode::Generate,
            shape: crate::model::retouch::RetouchShape::Strokes {
                strokes: self
                    .ai_remove
                    .draft
                    .iter()
                    .map(|s| std::sync::Arc::from(s.as_slice()))
                    .collect(),
                radius: t.size,
            },
            feather: t.feather,
            opacity: t.opacity,
            offset: [0.; 2],
            patch: None,
        };
        // What is still being typed in its panel reaches the program first:
        // its events and the request go to it in order.
        // One that can't be delivered stops the send: the request would go
        // with what the program had before, not what is shown.
        if let Some((offer, _)) = self.ai_remove_offer()
            && let Err(why) = self.commit_generator_panel(&offer)
        {
            self.messages
                .fail(format!("{} not sent: {why}", offer.name));
            return;
        }
        self.request_ai_remove(op);
        // Kept until the spot is made, and painted again if it isn't: a
        // refusal (a prompt missing, a key) or a failure leaves it to fix.
        if self.ai_remove.pending.is_some() || self.ai_remove.consent.is_some() {
            self.ai_remove.sent_draft = std::mem::take(&mut self.ai_remove.draft);
            // What Undo took back before the send stays so: repainting it
            // over a sent area would keep that area from coming back.
            self.ai_remove.undone_strokes.clear();
        }
    }
    /// Paints the area sent again, when nothing was made of it: unless
    /// something new is painted meanwhile.
    fn restore_ai_draft(&mut self) {
        let sent = std::mem::take(&mut self.ai_remove.sent_draft);
        if self.ai_remove.draft.is_empty() && !sent.is_empty() {
            self.ai_remove.draft = sent;
            // What Undo took back meanwhile was of another area, not this one.
            self.ai_remove.undone_strokes.clear();
        }
    }
    /// Sends `offer`'s panel's values still being typed to its program, as
    /// letting go of the field would; why one couldn't be, if one couldn't.
    fn commit_generator_panel(&mut self, offer: &Offer) -> Result<(), String> {
        let Some(panel) = &offer.panel else {
            return Ok(());
        };
        let unsent = self
            .extensions
            .panel(&offer.extension, panel)
            .map(crate::app::extensions::panels::unsent)
            .unwrap_or_default();
        for (control, value) in unsent {
            self.extensions
                .panel_changed(&offer.extension, panel, &control, value)?;
        }
        Ok(())
    }
    /// Whether `offer`'s extension said it needs setting up and its settings
    /// haven't changed since: a request would fail the same way.
    pub(in crate::app) fn ai_setup_needed(&self, offer: &Offer) -> bool {
        self.ai_remove.setup_needed.as_ref().is_some_and(|s| {
            s.extension == offer.extension
                && self.extensions.settings_fingerprint(&s.extension) == Some(s.settings)
                && self.extensions.mask_lifecycle(&s.extension) == s.lifecycle
        })
    }
    /// Why AI Remove can't run on the open photo now, for the tool to say.
    pub(in crate::app) fn ai_remove_unavailable(&self) -> Option<String> {
        if self.library.is_none() || self.document.catalog_photo.is_none() {
            return Some("Add this photo to a catalog to use this tool".into());
        }
        // Not from an editable preview, reduced: its patches would be the
        // original's edit.
        if self.document.opened_from_copy() {
            return Some("Connect the original to use AI Remove".into());
        }
        // Not on the half-size draft shown while the full size decodes: its
        // answer would be dropped once the full image replaces it.
        let Some(image) = self.document.full().filter(|im| !im.fast) else {
            return Some("Available once the photo has finished developing".into());
        };
        if self.document.edit.save_state().is_protected() {
            return Some("This edit is protected and cannot be changed here".into());
        }
        let recipe = self.document.edit.recipe();
        if let Some(why) = crate::develop::retouch::rendition::refusal(image, recipe) {
            return Some(why.into());
        }
        // As rendered: Detail switched off bypasses AI Denoise.
        if recipe.resolved(&image.metadata).ai_denoise.renders() && !self.document.ai.is_complete()
        {
            return Some("Available once AI Denoise has finished".into());
        }
        None
    }
    /// What must hold for a result to apply, read now.
    fn ai_remove_guard(&self, image: &Arc<CameraImage>, recipe: &Recipe) -> Guard {
        Guard {
            content: crate::app::develop::tools::subject_mask::content(recipe),
            // As rendered: Detail switched off bypasses its noise reduction.
            denoise: denoise(&recipe.resolved(&image.metadata)),
            ai: self
                .document
                .ai_source(image, &recipe.resolved(&image.metadata).ai_denoise),
            image: Arc::as_ptr(image) as usize,
            load: self.document.load_id(),
            file: self.document.file.clone(),
            photo: self
                .library
                .as_ref()
                .zip(self.document.catalog_photo)
                .map(|(l, id)| (format!("{:?}", l.session.catalog().location()), id)),
        }
    }
    /// The guard as it would be read now, if the photo is still decoded.
    fn ai_remove_guard_now(&self) -> Option<Guard> {
        let image = self.document.full()?.clone();
        Some(self.ai_remove_guard(&image, self.document.edit.recipe()))
    }

    /// The painted shape `op` is to be regenerated: asks for consent first
    /// when the generator uploads and the user hasn't agreed yet, then starts.
    pub(in crate::app) fn request_ai_remove(&mut self, op: RetouchOp) {
        match self.ai_remove_offer() {
            Some((offer, why)) => self.request_ai_remove_with(offer, why, op),
            None => self
                .messages
                .warn("Install AI Retouch in Preferences > Extensions to use it"),
        }
    }

    /// [`Editor::request_ai_remove`] with `offer`'s generator, which can't run
    /// for `why` when that is some.
    pub(in crate::app) fn request_ai_remove_with(
        &mut self,
        offer: Offer,
        why: Option<String>,
        mut op: RetouchOp,
    ) {
        self.context.request_repaint();
        if self.ai_remove.pending.is_some() {
            self.messages
                .note(format!("{} is still working on the last area", offer.name));
            return;
        }
        // The question stays with what was painted first: a new area would
        // replace it out of sight.
        if self.ai_remove.consent.is_some() {
            self.messages
                .note("Send or cancel the area painted first, then paint again");
            return;
        }
        if let Some(why) = self.ai_remove_unavailable() {
            self.messages.warn(why);
            return;
        }
        if self.document.edit.recipe().retouch.len() >= crate::model::retouch::MAX_OPS {
            self.messages.warn("Too many spots on this photo");
            return;
        }
        if let Some(why) = why {
            self.messages.warn(why);
            return;
        }
        if self.ai_setup_needed(&offer) {
            self.messages.warn(setup_first(&offer));
            return;
        }
        op.mode = RetouchMode::Generate;
        op.offset = [0.; 2];
        op.patch = None;
        self.dismiss_ai_failure();
        if offer.uploads && !self.extensions.uploads_allowed(&offer.extension) {
            self.ai_remove.consent = Some(Consent { offer, op });
            return;
        }
        self.start_ai_remove(offer, op);
    }

    /// The user's answer to the upload question: go on, or drop the request.
    pub(in crate::app) fn answer_ai_remove_consent(&mut self, allow: bool) {
        self.context.request_repaint();
        let Some(Consent { offer, op }) = self.ai_remove.consent.take() else {
            return;
        };
        if !allow {
            return self.restore_ai_draft();
        }
        if let Err(why) = self.extensions.allow_uploads(&offer.extension) {
            self.messages.fail(why);
            return self.restore_ai_draft();
        }
        // Checked again: the photo or the extension may have changed while asked.
        if let Some(why) = self.ai_remove_unavailable() {
            self.messages.warn(why);
            return self.restore_ai_draft();
        }
        self.start_ai_remove(offer, op);
        if self.ai_remove.pending.is_none() {
            self.restore_ai_draft();
        }
    }

    fn start_ai_remove(&mut self, offer: Offer, op: RetouchOp) {
        let Some(image) = self.document.full().cloned() else {
            return;
        };
        if let Err(why) = self.extensions.retouch_ready(&offer) {
            self.messages.warn(why);
            return;
        }
        let (Some(ledger), Some(lifecycle)) = (
            self.extensions.mask_ledger(&offer.extension),
            self.extensions.mask_lifecycle(&offer.extension),
        ) else {
            self.messages
                .warn(format!("{} isn't installed", offer.extension));
            return;
        };
        let load = self.document.load_id();
        let recipe = self.document.edit.recipe().clone();
        let guard = self.ai_remove_guard(&image, &recipe);
        let ai = guard.ai.clone();
        let ai_denoise = ai.is_some();
        let (generation, cancel) = self.ai_remove.task.start();
        self.messages.note(format!("{}…", offer.name));
        let job = retouch_generator::Prepare {
            load,
            generation,
            cancel: cancel.clone(),
            image,
            recipe,
            ai,
            op: op.clone(),
            ledger,
            generator: offer.generator.clone(),
        };
        let settings = self.extensions.settings_fingerprint(&offer.extension);
        self.ai_remove.pending = Some(Pending {
            offer,
            settings,
            op,
            guard,
            load,
            generation,
            cancel,
            lifecycle,
            ai_denoise,
            sent: None,
        });
        let (tx, ctx) = (self.tx.clone(), self.context.clone());
        self.ai_remove.worker.call(
            move || retouch_generator::prepare(job),
            move || retouch_generator::done(load, generation, Err(stopped())),
            tx,
            ctx,
        );
    }

    /// A request has its region rendered: it is sent, unless it was given up
    /// on meanwhile, when its buffers are let go of.
    pub(in crate::app) fn retouch_prepared(&mut self, prepared: retouch_generator::Prepared) {
        let (load, generation) = (prepared.load, prepared.generation);
        let current = self.ai_remove.pending.as_ref().is_some_and(|p| {
            p.load == load
                && p.generation == generation
                && p.sent.is_none()
                && self.ai_remove.task.id() == generation
        });
        if !current || load != self.document.load_id() {
            return self.settle_ai_remove();
        }
        if self.void_ai_remove_if_moved() {
            return;
        }
        let ready = match prepared.result {
            Ok(ready) => ready,
            Err(failure) => {
                return self.ai_remove_done(Done {
                    load,
                    generation,
                    result: Err(failure),
                });
            }
        };
        let offer = self
            .ai_remove
            .pending
            .as_ref()
            .map(|p| p.offer.clone())
            .expect("checked above");
        let asked = ready.params.clone();
        match self
            .extensions
            .generate_retouch(&offer, ready.params, ready.buffers)
        {
            Ok(ticket) => {
                if let Some(pending) = self.ai_remove.pending.as_mut() {
                    pending.sent = Some(Sent {
                        ticket,
                        asked,
                        input: ready.input,
                        rendition: ready.rendition,
                        region: ready.region,
                    });
                }
            }
            Err(why) => self.ai_remove_done(Done {
                load,
                generation,
                result: Err(Failure::Failed(why)),
            }),
        }
    }

    /// The one outcome of retouch request `ticket`: its answer is inverted
    /// into a patch on the worker thread, its failure ends the request. An
    /// outcome nothing waits for any more is dropped, and its buffers with it.
    pub(in crate::app) fn retouch_answered(
        &mut self,
        extension: &str,
        ticket: u64,
        result: Result<Value, RemoteError>,
        buffers: Option<Returned>,
    ) {
        let Some(pending) = &mut self.ai_remove.pending else {
            return;
        };
        if pending.offer.extension != extension
            || pending.sent.as_ref().is_none_or(|s| s.ticket != ticket)
        {
            return self.settle_ai_remove();
        }
        let Some(sent) = pending.sent.take() else {
            return;
        };
        let (load, generation, cancel) = (pending.load, pending.generation, pending.cancel.clone());
        let provenance = pending.offer.provenance.clone();
        let ai_denoise = pending.ai_denoise;
        let answer = result
            .map_err(retouch_generator::failure)
            .and_then(|value| {
                let answer: RetouchGenerated = serde_json::from_value(value)
                    .map_err(|e| Failure::Failed(format!("the extension's answer: {e}")))?;
                answer.validate().map_err(|e| {
                    Failure::Failed(format!("the extension's answer: {}", e.message))
                })?;
                Ok(answer)
            });
        let (answer, buffers) = match (answer, buffers) {
            (Ok(answer), Some(buffers)) => (answer, buffers),
            (result, _) => {
                let failure = result.err().unwrap_or_else(|| {
                    Failure::Failed("the extension answered without its result".into())
                });
                return self.ai_remove_done(Done {
                    load,
                    generation,
                    result: Err(failure),
                });
            }
        };
        let job = retouch_generator::Finish {
            load,
            generation,
            cancel,
            asked: sent.asked,
            input: sent.input,
            answer,
            buffers,
            rendition: sent.rendition,
            region: sent.region,
            provenance,
            ai_denoise,
        };
        let (tx, ctx) = (self.tx.clone(), self.context.clone());
        self.ai_remove.worker.call(
            move || retouch_generator::finish(job),
            move || retouch_generator::done(load, generation, Err(stopped())),
            tx,
            ctx,
        );
    }

    /// After the host's outcomes: AI Retouch closes once no generator is
    /// offered, a request whose extension moved on in its lifecycle is void,
    /// and one whose outcome can't come any more (gone from the host) ends
    /// now.
    pub(in crate::app) fn check_ai_remove(&mut self) {
        // AI Retouch with no generator left has nothing to run.
        self.close_tools_gone();
        if self.void_ai_remove_if_moved() {
            return;
        }
        if let Some(Pending {
            offer,
            sent: Some(sent),
            load,
            generation,
            ..
        }) = &self.ai_remove.pending
            && !self
                .extensions
                .retouch_in_flight(&offer.extension, sent.ticket)
        {
            let done = Done {
                load: *load,
                generation: *generation,
                result: Err(Failure::Failed(format!(
                    "{} stopped before it answered",
                    offer.extension_name
                ))),
            };
            self.ai_remove_done(done);
        }
        // A consent question for an extension that can't run any more is moot.
        if let Some(consent) = &self.ai_remove.consent
            && let Err(why) = self.extensions.retouch_ready(&consent.offer)
            && !why.contains("credential store")
        {
            self.ai_remove.consent = None;
            self.restore_ai_draft();
            self.messages.note(why);
        }
        self.settle_ai_remove();
    }

    /// Ends the running request at once if its extension has moved on in its
    /// lifecycle: busy clears, the worker's job is cancelled, a request sent
    /// is withdrawn and nothing is recorded. Returns whether it did.
    fn void_ai_remove_if_moved(&mut self) -> bool {
        let Some(pending) = &self.ai_remove.pending else {
            return false;
        };
        let now = self.extensions.mask_lifecycle(&pending.offer.extension);
        if now == Some(pending.lifecycle) {
            return false;
        }
        let (name, extension) = (
            pending.offer.name.clone(),
            pending.offer.extension_name.clone(),
        );
        self.ai_remove.cancel();
        self.restore_ai_draft();
        self.messages
            .note(format!("{name} stopped: {extension} was stopped"));
        self.settle_ai_remove();
        true
    }

    pub(in crate::app) fn cancel_ai_remove(&mut self) {
        self.context.request_repaint();
        let name = self
            .ai_remove
            .pending
            .as_ref()
            .map(|p| p.offer.name.clone());
        self.ai_remove.cancel();
        self.restore_ai_draft();
        self.settle_ai_remove();
        self.messages
            .note(Failure::Cancelled.message(name.as_deref().unwrap_or("The request")));
    }

    /// A request ended: its spot is added if it is still wanted and what it
    /// was made from still holds, else it is dropped.
    pub(in crate::app) fn ai_remove_done(&mut self, done: Done) {
        self.apply_ai_remove(done);
        // Ended without a spot: its area is painted again.
        if self.ai_remove.pending.is_none() {
            self.restore_ai_draft();
        }
        self.settle_ai_remove();
    }

    fn apply_ai_remove(&mut self, done: Done) {
        let result = done.result;
        let current = self
            .ai_remove
            .pending
            .as_ref()
            .is_some_and(|p| p.load == done.load && p.generation == done.generation);
        if done.load != self.document.load_id()
            || done.generation != self.ai_remove.task.id()
            || !current
        {
            self.discard_generated_patch(result.ok());
            return;
        }
        self.ai_remove.task.finish(done.generation);
        let Some(pending) = self.ai_remove.pending.take() else {
            self.discard_generated_patch(result.ok());
            return;
        };
        let generated = match result {
            Ok(generated) => generated,
            // Its extension was disabled or stopped it.
            Err(Failure::Cancelled) => {
                self.messages
                    .note(format!("{} stopped", pending.offer.name));
                return;
            }
            Err(failure) => {
                let id = &pending.offer.extension;
                let now = self.extensions.settings_fingerprint(id);
                if matches!(failure, Failure::NeedsSetup(_))
                    && let Some(settings) = now.filter(|now| Some(*now) == pending.settings)
                {
                    self.ai_remove.setup_needed = Some(SetupNeeded {
                        extension: id.clone(),
                        settings,
                        lifecycle: self.extensions.mask_lifecycle(id),
                    });
                }
                self.messages.fail(failure.message(&pending.offer.name));
                self.ai_remove.failure = Some(failure);
                self.ai_remove.failed = Some((pending.offer, pending.op));
                return;
            }
        };
        if self.extensions.mask_lifecycle(&pending.offer.extension) != Some(pending.lifecycle) {
            self.discard_generated_patch(Some(generated));
            return;
        }
        if self.ai_remove_guard_now().as_ref() != Some(&pending.guard)
            || self.document.edit.save_state().is_protected()
        {
            self.messages.warn(STALE);
            self.ai_remove.failure = Some(Failure::Failed(STALE.into()));
            self.discard_generated_patch(Some(generated));
            return;
        }
        // The patch, with every raster and patch the edit and its History hold.
        let edit = &self.document.edit;
        let history = edit.history().saved(edit.recipe());
        let held = history.mask_asset_ids();
        let ids: Vec<&str> = edit
            .recipe()
            .mask_asset_ids()
            .chain(held.iter().copied())
            .chain([generated.patch.id.as_str()])
            .collect();
        if crate::storage::mask_assets::decoded_bytes(ids) > crate::storage::mask_assets::EDIT_BYTES
        {
            self.messages.warn(
                "This photo's masks and spots use too much memory for another generated spot",
            );
            self.discard_generated_patch(Some(generated));
            return;
        }
        if self.document.edit.recipe().retouch.len() >= crate::model::retouch::MAX_OPS {
            self.messages.warn("Too many spots on this photo");
            self.discard_generated_patch(Some(generated));
            return;
        }
        let name = pending.offer.name.clone();
        let mut op = pending.op;
        op.patch = Some(generated.patch);
        // Checked as a save will check it, so the edit never holds what it can't save.
        if let Err(why) = op.validate() {
            let id = op.patch.as_ref().map(|p| p.id.clone()).unwrap_or_default();
            self.messages
                .fail(Failure::Failed(format!("{why:#}")).message(&pending.offer.name));
            self.ai_remove.failure = Some(Failure::Failed(format!("{why:#}")));
            self.discard_patch(&id);
            return;
        }
        // A drag still under way is recorded first, so undoing it keeps the spot,
        // and undoing the spot keeps the drag.
        if self.document.edit.history().in_gesture() {
            self.document.edit.finish_gesture();
        }
        let added = self.change_edit(
            Some(crate::app::history::Step::new(name.clone(), "")),
            |r| {
                r.add_retouch(op);
                r.retouch.len() - 1
            },
        );
        // A spot being dragged meanwhile keeps its own edit; the drag ends, so
        // its next frame can't write over the new spot now selected.
        self.view.retouch.end_spot_drag();
        self.view.retouch.selected = Some(added);
        self.ai_remove.sent_draft.clear();
        self.messages.done(format!("{name} done"));
    }

    /// Forgets the patch of a result the edit did not take.
    fn discard_generated_patch(&mut self, generated: Option<Generated>) {
        if let Some(generated) = generated {
            self.discard_patch(&generated.patch.id);
        }
    }

    /// Forgets an unsaved patch unless the edit, its History or Before still
    /// names it; decided once no request runs, as one may make the same one.
    fn discard_patch(&mut self, id: &str) {
        if self.ai_remove.pending.is_some() {
            self.ai_remove.deferred.push(id.to_string());
            return;
        }
        let edit = &self.document.edit;
        let named = edit.recipe().mask_asset_ids().any(|i| i == id)
            || edit
                .history()
                .saved(edit.recipe())
                .mask_asset_ids()
                .contains(id)
            || self
                .document
                .before
                .as_ref()
                .is_some_and(|r| r.mask_asset_ids().any(|i| i == id));
        if !named {
            crate::storage::mask_assets::discard_unsaved(id);
        }
    }

    /// Lets go of the patches set aside while a request ran, once none runs.
    fn settle_ai_remove(&mut self) {
        if self.ai_remove.pending.is_none() {
            for id in std::mem::take(&mut self.ai_remove.deferred) {
                self.discard_patch(&id);
            }
        }
    }
}

/// What a request whose worker job panicked, or whose worker is gone, ends in.
fn stopped() -> Failure {
    Failure::Failed("it stopped unexpectedly".into())
}

